import {
  FEATURE_FLAG_DEFINITIONS,
  FEATURE_FLAG_KEYS,
} from "@/config/feature-flags";
import { planAtLeast } from "@/config/plan-limits";
import { ROLE_RANK } from "@/types/member";
import type {
  FeatureFlagKey,
  FeatureFlagSnapshot,
  FlagContext,
} from "@/types/feature-flag";

/**
 * Feature-flag evaluation, shared verbatim by server and client.
 *
 * Server code builds a `FlagContext` from the session and calls `isEnabled()`
 * directly; the dashboard layout serialises `snapshotFlags()` into the client
 * provider so `useFeatureFlag()` answers the same way without a round trip.
 * Both sides must agree — never re-implement a strategy at a call site.
 */
export function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {
  const definition = FEATURE_FLAG_DEFINITIONS[flag];
  if (!definition) return false;

  if (definition.overridable && ctx.overrides?.includes(flag)) {
    return true;
  }

  const strategy = definition.strategy;
  switch (strategy.kind) {
    case "off":
      return false;
    case "on":
      return true;
    case "plan":
      return planAtLeast(ctx.plan, strategy.minPlan);
    case "role":
      return ctx.role !== null && ROLE_RANK[ctx.role] >= ROLE_RANK[strategy.minRole];
    case "percentage":
      return bucketOf(flag, ctx) < strategy.percent;
    default:
      return false;
  }
}

/** Evaluates every flag at once, for handoff to the client provider. */
export function snapshotFlags(ctx: FlagContext): FeatureFlagSnapshot {
  const snapshot = {} as Record<FeatureFlagKey, boolean>;
  for (const key of FEATURE_FLAG_KEYS) {
    snapshot[key] = isEnabled(key, ctx);
  }
  return snapshot;
}

/** Throwing guard for server actions gated behind a flag. */
export class FeatureDisabledError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: FeatureFlagKey) {
    super(`Feature "${flag}" is not enabled for this organization.`);
    this.name = "FeatureDisabledError";
  }
}

export function assertEnabled(flag: FeatureFlagKey, ctx: FlagContext): void {
  if (!isEnabled(flag, ctx)) {
    throw new FeatureDisabledError(flag);
  }
}

/**
 * Deterministic 0–99 bucket for percentage rollouts. Stable per
 * (flag, org, user) so a viewer never sees the feature flicker.
 */
function bucketOf(flag: FeatureFlagKey, ctx: FlagContext): number {
  const seed = `${flag}:${ctx.orgId ?? "-"}:${ctx.userId ?? "-"}`;
  let hash = 2_166_136_261;
  for (let i = 0; i < seed.length; i += 1) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16_777_619);
  }
  return Math.abs(hash) % 100;
}
"use client";

/**
 * Reads one flag from the `FeatureFlagProvider` snapshot.
 *
 * Must call (do not reimplement): isEnabled
 */
import { useContext } from "react";
import type { FeatureFlagKey } from "@/types/feature-flag";
import { FlagSnapshotContext, readFlag } from "./flag-context";

export function useFeatureFlag(flag: FeatureFlagKey): boolean {
  const snapshot = useContext(FlagSnapshotContext);
  return readFlag(snapshot, flag);
}
"use client";

/**
 * Client-side plumbing for feature flags.
 *
 * The server evaluates every flag once per request with `snapshotFlags()` and
 * serialises the result into `FeatureFlagProvider`. The client therefore reads
 * the snapshot rather than re-deriving anything — but when a key is missing
 * (a snapshot serialised before a newly shipped flag existed) we fall back to
 * `isEnabled()` so there is still exactly one evaluator in the codebase.
 */
import { createContext } from "react";
import { isEnabled } from "@/lib/feature-flags";
import type {
  FeatureFlagKey,
  FeatureFlagSnapshot,
  FlagContext,
} from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";

/** Context for a signed-out / pre-hydration reader: free plan, no role. */
export const ANONYMOUS_FLAG_CONTEXT: FlagContext = {
  orgId: null,
  userId: null,
  plan: "free",
  role: null,
};

/** The full evaluation context for a member browsing one organization. */
export function orgFlagContext(org: Organization, actor: Actor): FlagContext {
  return {
    orgId: org.id,
    userId: actor.userId,
    plan: org.plan,
    role: actor.role,
    overrides: org.settings.enabledFlagOverrides,
  };
}

/**
 * Reads one flag out of a server-evaluated snapshot, falling back to a live
 * `isEnabled()` evaluation when the snapshot predates the flag.
 */
export function readFlag(
  snapshot: FeatureFlagSnapshot | null,
  flag: FeatureFlagKey,
  context: FlagContext = ANONYMOUS_FLAG_CONTEXT,
): boolean {
  const evaluated = snapshot?.[flag];
  return typeof evaluated === "boolean"
    ? evaluated
    : isEnabled(flag, context);
}

export const FlagSnapshotContext = createContext<FeatureFlagSnapshot | null>(
  null,
);
import type {
  FeatureFlagDefinition,
  FeatureFlagKey,
} from "@/types/feature-flag";

/**
 * Declarative registry of every feature flag. `isEnabled()` in
 * `src/lib/feature-flags.ts` is the only reader — UI and server code go
 * through that function, never through this table directly.
 */
export const FEATURE_FLAG_DEFINITIONS: Readonly<
  Record<FeatureFlagKey, FeatureFlagDefinition>
> = {
  kanban_board: {
    key: "kanban_board",
    label: "Kanban board",
    description: "Drag-and-drop board view for a project's issues.",
    strategy: { kind: "plan", minPlan: "starter" },
    overridable: true,
  },
  ai_issue_summary: {
    key: "ai_issue_summary",
    label: "AI issue summary",
    description: "Generates a short summary of a long issue thread.",
    strategy: { kind: "percentage", percent: 25 },
    overridable: true,
  },
  command_palette: {
    key: "command_palette",
    label: "Command palette",
    description: "Ctrl+K quick navigation and actions.",
    strategy: { kind: "on" },
    overridable: false,
  },
  activity_feed: {
    key: "activity_feed",
    label: "Activity feed",
    description: "Organization-wide audit trail view.",
    strategy: { kind: "plan", minPlan: "growth" },
    overridable: true,
  },
  public_projects: {
    key: "public_projects",
    label: "Public projects",
    description: "Share a read-only project page outside the organization.",
    strategy: { kind: "plan", minPlan: "enterprise" },
    overridable: true,
  },
  webhooks: {
    key: "webhooks",
    label: "Outgoing webhooks",
    description: "Deliver domain events to an external HTTP endpoint.",
    strategy: { kind: "plan", minPlan: "growth" },
    overridable: false,
  },
  csv_export: {
    key: "csv_export",
    label: "CSV export",
    description: "Export issues and the audit log as CSV.",
    strategy: { kind: "plan", minPlan: "starter" },
    overridable: true,
  },
  digest_email: {
    key: "digest_email",
    label: "Daily digest email",
    description: "Batches notifications into one daily email.",
    strategy: { kind: "plan", minPlan: "growth" },
    overridable: true,
  },
  issue_templates: {
    key: "issue_templates",
    label: "Issue templates",
    description: "Prefilled issue bodies per project.",
    strategy: { kind: "role", minRole: "admin" },
    overridable: true,
  },
  advanced_search: {
    key: "advanced_search",
    label: "Advanced search",
    description: "Field-scoped query syntax across issues and comments.",
    strategy: { kind: "plan", minPlan: "enterprise" },
    overridable: true,
  },
};

export const FEATURE_FLAG_KEYS = Object.keys(
  FEATURE_FLAG_DEFINITIONS,
) as readonly FeatureFlagKey[];

export function getFlagDefinition(key: FeatureFlagKey): FeatureFlagDefinition {
  return FEATURE_FLAG_DEFINITIONS[key];
}

export function isFeatureFlagKey(value: string): value is FeatureFlagKey {
  return Object.prototype.hasOwnProperty.call(FEATURE_FLAG_DEFINITIONS, value);
}
import type { OrgId, UserId } from "./common";
import type { PlanId } from "./billing";
import type { Role } from "./member";

/**
 * Every feature flag known to Taskflow. Adding a key here obliges you to add a
 * matching entry to `FEATURE_FLAG_DEFINITIONS` in `src/config/feature-flags.ts`
 * — the type is what keeps the two in sync.
 */
export type FeatureFlagKey =
  | "kanban_board"
  | "ai_issue_summary"
  | "command_palette"
  | "activity_feed"
  | "public_projects"
  | "webhooks"
  | "csv_export"
  | "digest_email"
  | "issue_templates"
  | "advanced_search";

export type FlagRolloutStrategy =
  | { readonly kind: "off" }
  | { readonly kind: "on" }
  | { readonly kind: "plan"; readonly minPlan: PlanId }
  | { readonly kind: "role"; readonly minRole: Role }
  | { readonly kind: "percentage"; readonly percent: number };

export interface FeatureFlagDefinition {
  readonly key: FeatureFlagKey;
  readonly label: string;
  readonly description: string;
  readonly strategy: FlagRolloutStrategy;
  /** When true the org-level override in `OrganizationSettings` can turn it on. */
  readonly overridable: boolean;
}

/**
 * Evaluation context passed to `isEnabled()`. The same shape is used on the
 * server (built from the session) and in the client via `useFeatureFlag`.
 */
export interface FlagContext {
  readonly orgId: OrgId | null;
  readonly userId: UserId | null;
  readonly plan: PlanId;
  readonly role: Role | null;
  readonly overrides?: readonly string[];
}

/** Serialisable snapshot handed from a server layout to the client provider. */
export type FeatureFlagSnapshot = Readonly<Record<FeatureFlagKey, boolean>>;

